mapper.select:
SELECT * FROM( SELECT management_attach_id, ssci.COMPANY_NAME AS dataSources, ssci.COMPANY_NAME AS COMPANY_NAME, ssci.COMPANY_CODE AS COMPANY_CODE, ''AS FILE_RECORD_ID, ''AS FORM_ID, 'MANAGEMENT_ATTACH'AS FORM_TYPE, fileupload_id AS FILE_ID, AUTH_TYPE, END_DATE,AUTH_DESCRIPTION, AUTH_NUM, AUTH_DATE, AUTH_ORG, cuma.CREATION_DATE, cuma.IS_USE_REMINDER ,cuma.COMPANY_ID as companyId,'资质信息' AS documentType FROM ceea_sup_management_attach cuma, scc_sup_company_info ssci WHERE cuma.COMPANY_ID = ssci.COMPANY_ID and cuma.END_DATE is not null AND ssci.COMPANY_CODE !='' and ssci.STATUS='APPROVED' and ssci.PJ_COMPANY_STATUS in ('QUASI_SUPPLIER','OFFICIAL_SUPPLIER','SLUGGISH_SUPPLIER') and ssci.IS_BACKLIST = 'N' and ssci.TIME_LIMIT_FLAG = 'N' UNION ALL
SELECT company_id AS management_attach_id, COMPANY_NAME AS dataSources, COMPANY_NAME, COMPANY_CODE, '' AS FILE_RECORD_ID, '' AS FORM_ID, 'COMPANY_INFO'AS FORM_TYPE, BUSINESS_LICENSE_FILE_ID AS FILE_ID, BUSINESS_LICENSE AS AUTH_TYPE, BUSINESS_END_DATE AS END_DATE, '' AS AUTH_DESCRIPTION,'' AS AUTH_NUM, NULL AS AUTH_DATE,'' AS AUTH_ORG, CREATION_DATE, IS_USE_REMINDER,COMPANY_ID as companyId, CASE WHEN OVERSEAS_RELATION = 'PERSONAL' THEN '身份证' ELSE '营业执照' END AS documentType FROM scc_sup_company_info WHERE BUSINESS_END_DATE is not NULL AND COMPANY_CODE !='' AND STATUS ='APPROVED' and PJ_COMPANY_STATUS in ('QUASI_SUPPLIER','OFFICIAL_SUPPLIER','SLUGGISH_SUPPLIER') and IS_BACKLIST = 'N' and TIME_LIMIT_FLAG = 'N' )attachMix
COMPANY_CODE = #{managementAttachRequestDTO.companyCode}
AND COMPANY_NAME like concat('%',#{managementAttachRequestDTO.companyName},'%')
AND END_DATE >= #{authDate}
AND IS_USE_REMINDER = #{managementAttachRequestDTO.isUseReminder}
AND IS_USE_REMINDER = 'Y'
AND END_DATE <= #{endDate}
AND AUTH_TYPE !='' AND AUTH_TYPE IS NOT NULL
ORDER BY END_DATE
